'use strict';
const $=id=>document.getElementById(id);const sizes={A4:[210,297],A3:[297,420],A5:[148,210],Letter:[215.9,279.4],Legal:[215.9,355.6],Tabloid:[279.4,431.8]};
const defaults=()=>({size:'A4',orientation:'Portrait',unit:'mm',width:210,height:297,fit:'Fit',same:true,top:12,bottom:12,left:12,right:12,background:'White',color:'#FFFFFF',layout:'1 × 1',cols:2,rows:2,gapX:5,gapY:5,gridMargin:0,alignX:'Center',alignY:'Middle',quality:150});let settings=defaults(),images=[],selected=null,currentPage=0,busy=false,downloadUrl=null,dragged=null;
const edits=()=>({rotation:0,flipX:false,flipY:false,brightness:100,contrast:100,saturation:100,grayscale:false,sharpen:0,crop:{x:0,y:0,w:100,h:100},customW:100,customH:100,x:0,y:0,lock:true});
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4500)}
function selectField(label,key,values,value){return `<label>${label}<select data-key="${key}">${values.map(v=>`<option ${v===value?'selected':''}>${v}</option>`).join('')}</select></label>`}
function num(label,key,value,min=0,max=2000,step=1){return `<label>${label}<input data-key="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${value}"></label>`}
function check(label,key,value){return `<label class="check"><input type="checkbox" data-key="${key}" ${value?'checked':''}>${label}</label>`}
function section(title,content,open=false){return `<details ${open?'open':''}><summary>${title}</summary><div class="fields">${content}</div></details>`}
function settingsUI(){let s=settings;$('settings').innerHTML=section('Page & orientation',selectField('Page size','size',[...Object.keys(sizes),'Custom'],s.size)+ (s.size==='Custom'?`<div class="row">${num('Width','width',s.width,1)}${num('Height','height',s.height,1)}</div>`+selectField('Unit','unit',['mm','cm','inches','pixels'],s.unit):'')+selectField('Orientation','orientation',['Portrait','Landscape','Auto'],s.orientation),true)+section('Image placement',selectField('Fit mode','fit',['Fit','Fill','Stretch','Original Size','Custom'],s.fit)+`<div class="row">${selectField('Horizontal','alignX',['Left','Center','Right'],s.alignX)}${selectField('Vertical','alignY',['Top','Middle','Bottom'],s.alignY)}</div><small>Custom sizing and position are available in each image’s editor. Dimensions use mm unless specified.</small>`,true)+section('Margins',selectField('Preset','preset',['Custom','No margin','Small','Medium','Large'],'Custom')+check('Use same margin on all sides','same',s.same)+`<div class="row">${num('Top (mm)','top',s.top)}${num('Bottom (mm)','bottom',s.bottom)}${num('Left (mm)','left',s.left)}${num('Right (mm)','right',s.right)}</div>`,true)+section('Page background',selectField('Background','background',['White','Black','Transparent','Custom color'],s.background)+`<div class="row"><label>Color<input type="color" data-key="color" value="${s.color}"></label><label>HEX<input data-key="color" value="${s.color}" pattern="#[0-9a-fA-F]{6}" maxlength="7"></label></div><small>Transparent pages show white in most PDF readers.</small>`)+section('Multiple images per page',selectField('Grid (columns × rows)','layout',['1 × 1','1 × 2','2 × 1','2 × 2','3 × 2','3 × 3','Custom grid'],s.layout)+(s.layout==='Custom grid'?`<div class="row">${num('Columns','cols',s.cols,1,10)}${num('Rows','rows',s.rows,1,10)}</div>`:'')+`<div class="row">${num('Horizontal gap (mm)','gapX',s.gapX)}${num('Vertical gap (mm)','gapY',s.gapY)}</div>`+num('Grid inset (mm)','gridMargin',s.gridMargin))+section('Export quality',selectField('Resolution (DPI)','quality',[96,150,300],s.quality)+`<small>Higher resolution creates larger files. Image dimensions are limited to 5,000 pixels per page edge.</small>`);
}
$('settings').addEventListener('change',e=>{const k=e.target.dataset.key;if(!k)return;let val=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?Number(e.target.value):e.target.value;if(e.target.type==='number'&&(!Number.isFinite(val)||val<Number(e.target.min)||val>Number(e.target.max))){toast('Enter a value within the displayed limits.');settingsUI();return}if(k==='color'&&!/^#[\da-f]{6}$/i.test(val)){toast('Use a HEX color like #FFFFFF.');return}if(k==='preset'){const m={'No margin':0,Small:5,Medium:12,Large:25}[val];if(m!==undefined)for(const key of ['top','bottom','left','right'])settings[key]=m;settingsUI()}else{settings[k]=val;if(['top','bottom','left','right'].includes(k)&&settings.same){for(const key of ['top','bottom','left','right'])settings[key]=val;settingsUI()}if(['size','layout'].includes(k))settingsUI()}refresh()});
$('settings').addEventListener('input',ev=>{const k=ev.target.dataset.key;if(ev.target.type!=='number'||!k)return;const v=Number(ev.target.value);if(!ev.target.value||!Number.isFinite(v)||v<Number(ev.target.min)||v>Number(ev.target.max))return;settings[k]=v;if(['top','bottom','left','right'].includes(k)&&settings.same){for(const side of ['top','bottom','left','right']){settings[side]=v;const input=$('settings').querySelector('[data-key="'+side+'"]');if(input!==ev.target)input.value=v}}refresh()});
async function addFiles(files){if(busy)return;let rejected=0;for(const f of Array.from(files)){if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>30*1024*1024||images.length>=100){rejected++;continue}const url=URL.createObjectURL(f);try{const img=new Image;img.src=url;await img.decode();if(img.naturalWidth*img.naturalHeight>60000000)throw Error('Image too large');images.push({id:crypto.randomUUID(),name:f.name,size:f.size,img,url,e:edits()});if(!selected)selected=images.at(-1).id}catch{URL.revokeObjectURL(url);rejected++}}if(rejected)toast(`${rejected} file(s) skipped. Use JPG, PNG, or WEBP under 30 MB and 60 megapixels. Limit: 100 images.`);refresh(true)}
$('files').onchange=e=>{addFiles(e.target.files);e.target.value=''};for(const event of ['dragenter','dragover'])$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.add('over')});for(const event of ['dragleave','drop'])$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.remove('over');if(event==='drop')addFiles(e.dataTransfer.files)});
function renderedImage(item,max=2000){const e=item.e,c=e.crop,sw=item.img.naturalWidth*c.w/100,sh=item.img.naturalHeight*c.h/100,rot=e.rotation%180!==0;let w=rot?sh:sw,h=rot?sw:sh,scale=Math.min(1,max/Math.max(w,h));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(w*scale));canvas.height=Math.max(1,Math.round(h*scale));const ctx=canvas.getContext('2d',{willReadFrequently:e.sharpen>0});ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(e.rotation*Math.PI/180);ctx.scale(e.flipX?-1:1,e.flipY?-1:1);ctx.filter=`brightness(${e.brightness}%) contrast(${e.contrast}%) saturate(${e.saturation}%) grayscale(${e.grayscale?1:0})`;ctx.drawImage(item.img,item.img.naturalWidth*c.x/100,item.img.naturalHeight*c.y/100,sw,sh,-sw*scale/2,-sh*scale/2,sw*scale,sh*scale);if(e.sharpen>0){const pixels=ctx.getImageData(0,0,canvas.width,canvas.height),src=new Uint8ClampedArray(pixels.data),data=pixels.data,a=e.sharpen/100;for(let y=1;y<canvas.height-1;y++)for(let x=1;x<canvas.width-1;x++){const p=(y*canvas.width+x)*4;for(let k=0;k<3;k++)data[p+k]=src[p+k]*(1+4*a)-a*(src[p-4+k]+src[p+4+k]+src[p-canvas.width*4+k]+src[p+canvas.width*4+k])}ctx.putImageData(pixels,0,0)}return {canvas,w,h}}
function imageList(){const root=$('images');root.replaceChildren();images.forEach((item,i)=>{const card=document.createElement('article');card.className='card'+(selected===item.id?' selected':'');card.draggable=true;card.tabIndex=0;card.setAttribute('aria-label',`Image ${i+1}: ${item.name}. Select to edit.`);const thumb=renderedImage(item,220).canvas;card.append(thumb);const n=document.createElement('span');n.className='number';n.textContent=String(i+1).padStart(2,'0');card.append(n);const title=document.createElement('strong');title.textContent=item.name;card.append(title);const meta=document.createElement('small');meta.textContent=`${(item.size/1024).toFixed(0)} KB · ${item.img.naturalWidth} × ${item.img.naturalHeight}`;card.append(meta);const actions=document.createElement('div');actions.className='actions';for(const [action,text,label] of [['left','‹','Move left'],['right','›','Move right'],['rotateLeft','↶','Rotate left'],['rotateRight','↷','Rotate right'],['duplicate','⧉','Duplicate'],['delete','×','Delete']]){const b=document.createElement('button');b.textContent=text;b.title=label;b.setAttribute('aria-label',label);b.disabled=busy||(action==='left'&&i===0)||(action==='right'&&i===images.length-1);b.onclick=ev=>{ev.stopPropagation();imageAction(item.id,action)};actions.append(b)}card.append(actions);card.onclick=()=>{if(busy)return;selected=item.id;imageList();editorUI()};card.onkeydown=ev=>{if(ev.key==='Enter')card.click()};card.ondragstart=ev=>{if(busy){ev.preventDefault();return}dragged=item.id;ev.dataTransfer.setData('text/plain',item.id);ev.dataTransfer.effectAllowed='move'};card.ondragover=ev=>ev.preventDefault();card.ondrop=ev=>{ev.preventDefault();if(busy)return;const from=images.findIndex(x=>x.id===dragged),to=images.findIndex(x=>x.id===item.id);if(from>=0&&from!==to){images.splice(to,0,images.splice(from,1)[0]);refresh(true)}};root.append(card)});$('empty').hidden=images.length>0;$('imagecount').textContent=`${images.length} image${images.length===1?'':'s'}`}
function imageAction(id,action){if(busy)return;const i=images.findIndex(x=>x.id===id),item=images[i];if(!item)return;if(action==='delete'){images.splice(i,1);if(!images.some(x=>x.url===item.url))URL.revokeObjectURL(item.url);if(selected===id)selected=images[Math.min(i,images.length-1)]?.id||null}else if(action==='duplicate'){if(images.length>=100)return toast('Limit: 100 images.');images.splice(i+1,0,{...item,id:crypto.randomUUID(),e:structuredClone(item.e)})}else if(action==='left'&&i>0)[images[i-1],images[i]]=[images[i],images[i-1]];else if(action==='right'&&i<images.length-1)[images[i+1],images[i]]=[images[i],images[i+1]];else if(action==='rotateLeft')item.e.rotation=(item.e.rotation+270)%360;else if(action==='rotateRight')item.e.rotation=(item.e.rotation+90)%360;else if(action==='flipX'||action==='flipY')item.e[action]=!item.e[action];else if(action==='reset')item.e=edits();refresh(true)}
function editorUI(){const item=images.find(x=>x.id===selected);if(!item){$('editor').replaceChildren();return}const e=item.e;$('editor').innerHTML=`<h3>Edit selected image</h3><div class="actions">${[['rotateLeft','Rotate left'],['rotateRight','Rotate right'],['flipX','Flip horizontal'],['flipY','Flip vertical'],['reset','Reset image']].map(([k,label])=>`<button data-action="${k}">${label}</button>`).join('')}</div>`+section('Crop · percentages of original image',`<small>Set the crop origin and size. Edits preserve your original file.</small><div class="row">${num('Left (%)','crop.x',e.crop.x,0,99)}${num('Top (%)','crop.y',e.crop.y,0,99)}${num('Width (%)','crop.w',e.crop.w,1,100)}${num('Height (%)','crop.h',e.crop.h,1,100)}</div>`)+section('Image adjustments',['brightness','contrast','saturation','sharpen'].map(k=>`<label>${k[0].toUpperCase()+k.slice(1)} <span id="value-${k}">${e[k]}%</span><input type="range" min="0" max="${k==='sharpen'?100:200}" value="${e[k]}" data-key="${k}"></label>`).join('')+check('Grayscale','grayscale',e.grayscale))+section('Size & position',`<small>Position offsets apply in all fit modes. Width and height apply in Custom mode.</small><div class="row">${num('Width (mm)','customW',e.customW,1)}${num('Height (mm)','customH',e.customH,1)}${num('X offset (mm)','x',e.x,-2000)}${num('Y offset (mm)','y',e.y,-2000)}</div>`+check('Lock aspect ratio','lock',e.lock));}
$('editor').onclick=ev=>{const a=ev.target.dataset.action;if(a)imageAction(selected,a)};$('editor').addEventListener('input',ev=>{const k=ev.target.dataset.key,item=images.find(x=>x.id===selected);if(!k||!item||busy)return;const v=ev.target.type==='checkbox'?ev.target.checked:Number(ev.target.value);if(typeof v==='number'&&(!Number.isFinite(v)||v<Number(ev.target.min)||v>Number(ev.target.max)))return;if(k.startsWith('crop.')){item.e.crop[k.split('.')[1]]=v;const c=item.e.crop;c.w=Math.min(c.w,100-c.x);c.h=Math.min(c.h,100-c.y)}else{item.e[k]=v;if(item.e.lock&&['customW','customH'].includes(k)){const {w,h}=renderedImage(item,10);if(k==='customW')item.e.customH=v*h/w;else item.e.customW=v*w/h}}if($('value-'+k))$('value-'+k).textContent=v+'%';refresh();});$('editor').addEventListener('change',()=>{imageList();editorUI()});
function grid(){if(settings.layout==='Custom grid')return [+settings.cols,+settings.rows];return settings.layout.split(' × ').map(Number)}
function pageSize(items){let [w,h]=settings.size==='Custom'?[settings.width,settings.height].map(v=>v*({mm:1,cm:10,inches:25.4,pixels:25.4/96}[settings.unit])):sizes[settings.size];let landscape=settings.orientation==='Landscape';if(settings.orientation==='Auto'&&items[0]){const d=renderedImage(items[0],10);landscape=d.w>d.h}if(landscape&&w<h||!landscape&&w>h)[w,h]=[h,w];return {w,h}}
function pageGroups(){const [cols,rows]=grid(),n=cols*rows,groups=[];for(let i=0;i<images.length;i+=n)groups.push(images.slice(i,i+n));return groups}
function drawPage(items,dpi=96){const s=settings,{w,h}=pageSize(items),[cols,rows]=grid();const scale=Math.min(dpi/25.4,5000/Math.max(w,h));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(w*scale));c.height=Math.max(1,Math.round(h*scale));const ctx=c.getContext('2d');ctx.scale(scale,scale);if(s.background!=='Transparent'){ctx.fillStyle=s.background==='White'?'#FFFFFF':s.background==='Black'?'#000000':s.color;ctx.fillRect(0,0,w,h)}const cw=(w-s.left-s.right-2*s.gridMargin-(cols-1)*s.gapX)/cols,ch=(h-s.top-s.bottom-2*s.gridMargin-(rows-1)*s.gapY)/rows;if(cw<=0||ch<=0)throw Error('Margins and spacing leave no room for images. Reduce them to continue.');items.forEach((item,i)=>{const {canvas,w:iw,h:ih}=renderedImage(item,Math.min(5000,Math.max(c.width,c.height)));const left=s.left+s.gridMargin+(i%cols)*(cw+s.gapX),top=s.top+s.gridMargin+Math.floor(i/cols)*(ch+s.gapY);let dw=cw,dh=ch;if(s.fit==='Fit'||s.fit==='Fill'){const r=(s.fit==='Fit'?Math.min:Math.max)(cw/iw,ch/ih);dw=iw*r;dh=ih*r}else if(s.fit==='Original Size'){dw=iw*25.4/96;dh=ih*25.4/96;const r=Math.min(1,cw/dw,ch/dh);dw*=r;dh*=r}else if(s.fit==='Custom'){dw=item.e.customW;dh=item.e.customH}const x=left+(cw-dw)*({Left:0,Center:.5,Right:1}[s.alignX])+item.e.x,y=top+(ch-dh)*({Top:0,Middle:.5,Bottom:1}[s.alignY])+item.e.y;ctx.save();ctx.beginPath();ctx.rect(left,top,cw,ch);ctx.clip();ctx.drawImage(canvas,x,y,dw,dh);ctx.restore()});return {canvas:c,w,h}}
function invalidateDownload(){if(downloadUrl){URL.revokeObjectURL(downloadUrl);downloadUrl=null;$('download').replaceChildren()}}
function refresh(full=false){invalidateDownload();if(full){imageList();editorUI()}const groups=pageGroups();currentPage=Math.min(currentPage,Math.max(0,groups.length-1));$('generate').disabled=images.length===0||busy;$('clear').disabled=busy||!images.length;$('pagecount').textContent=groups.length?`Page ${currentPage+1} of ${groups.length}`:'0 pages';$('exportinfo').textContent=images.length?`${groups.length} page${groups.length===1?'':'s'} · processed on your device`:'Add images to get started';$('previous').disabled=currentPage===0;$('next').disabled=currentPage>=groups.length-1;const s=pageSize(groups[currentPage]||[]);$('previewlabel').textContent=`${settings.size} · ${s.w>s.h?'Landscape':'Portrait'} · ${Math.round(s.w)} × ${Math.round(s.h)} mm`;if(!groups.length){$('preview').innerHTML='<div class="blankpage"><span>▧</span><p>Your PDF starts here</p><small>Add an image to see the preview</small></div>';return}try{const {canvas}=drawPage(groups[currentPage],65);canvas.style.width=(Math.min(320,$('preview').clientWidth-56)*+$('zoom').value)+'px';canvas.style.height='auto';canvas.setAttribute('aria-label',`Preview of PDF page ${currentPage+1}`);$('preview').replaceChildren(canvas)}catch(err){$('preview').textContent=err.message;$('generate').disabled=true}}
$('previous').onclick=()=>{currentPage--;refresh()};$('next').onclick=()=>{currentPage++;refresh()};$('zoom').onchange=()=>refresh();$('clear').onclick=()=>{if(busy)return;new Set(images.map(x=>x.url)).forEach(URL.revokeObjectURL);images=[];selected=null;refresh(true)};$('resetsettings').onclick=()=>{if(busy)return;settings=defaults();settingsUI();refresh()};$('help').onclick=()=>$('helpdialog').showModal();
const encoder=new TextEncoder();async function compress(bytes){if(typeof CompressionStream==='undefined')return {bytes,filter:''};const stream=new Blob([bytes]).stream().pipeThrough(new CompressionStream('deflate'));return {bytes:new Uint8Array(await new Response(stream).arrayBuffer()),filter:'/Filter /FlateDecode '}}
async function makePDF(){const groups=pageGroups(),objects=[],chunks=[],offsets=[0];let length=0;const add=data=>{const b=typeof data==='string'?encoder.encode(data):data;chunks.push(b);length+=b.length};const obj=value=>{objects.push(value);return objects.length};obj('<< /Type /Catalog /Pages 2 0 R >>');obj(null);const pageIds=[];for(let i=0;i<groups.length;i++){$('generate').textContent=`Preparing page ${i+1} of ${groups.length}…`;await new Promise(r=>setTimeout(r,0));const {canvas,w,h}=drawPage(groups[i],+settings.quality);const rgba=canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data,rgb=new Uint8Array(canvas.width*canvas.height*3),alpha=settings.background==='Transparent'?new Uint8Array(canvas.width*canvas.height):null;for(let p=0,j=0;p<rgba.length;p+=4,j++){rgb[j*3]=rgba[p];rgb[j*3+1]=rgba[p+1];rgb[j*3+2]=rgba[p+2];if(alpha)alpha[j]=rgba[p+3]}let maskId=0;if(alpha){const z=await compress(alpha);maskId=obj({dict:`/Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceGray /BitsPerComponent 8 ${z.filter}`,bytes:z.bytes})}const z=await compress(rgb),imageId=obj({dict:`/Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 ${z.filter}${maskId?`/SMask ${maskId} 0 R `:''}`,bytes:z.bytes}),pw=(w*72/25.4).toFixed(4),ph=(h*72/25.4).toFixed(4);const contentId=obj({dict:'',bytes:encoder.encode(`q ${pw} 0 0 ${ph} 0 0 cm /Im0 Do Q`)});pageIds.push(obj(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pw} ${ph}] /Resources << /XObject << /Im0 ${imageId} 0 R >> >> /Contents ${contentId} 0 R >>`))}objects[1]=`<< /Type /Pages /Count ${pageIds.length} /Kids [${pageIds.map(id=>id+' 0 R').join(' ')}] >>`;add('%PDF-1.4\n');objects.forEach((o,i)=>{offsets.push(length);add(`${i+1} 0 obj\n`);if(typeof o==='string')add(o+'\n');else{add(`<< ${o.dict}/Length ${o.bytes.length} >>\nstream\n`);add(o.bytes);add('\nendstream\n')}add('endobj\n')});const start=length;add(`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`);offsets.slice(1).forEach(offset=>add(`${String(offset).padStart(10,'0')} 00000 n \n`));add(`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`);return new Blob(chunks,{type:'application/pdf'})}
$('generate').onclick=async()=>{if(busy||!images.length)return;busy=true;document.querySelectorAll('.workspace input,.workspace select,.workspace button').forEach(x=>x.disabled=true);try{const blob=await makePDF();invalidateDownload();downloadUrl=URL.createObjectURL(blob);const link=document.createElement('a');link.href=downloadUrl;link.download=($('filename').value.replace(/[<>:"/\\|?*\x00-\x1f]/g,'').replace(/\.pdf$/i,'').trim()||'my-images')+'.pdf';link.textContent=`Download PDF · ${(blob.size/1024/1024).toFixed(1)} MB`;$('download').replaceChildren(link);link.click();toast('Your PDF is ready. You can download it again below.')}catch(err){toast('Could not generate PDF: '+err.message)}finally{busy=false;document.querySelectorAll('.workspace input,.workspace select,.workspace button').forEach(x=>x.disabled=false);$('generate').textContent='↓  Generate PDF';imageList();$('previous').disabled=currentPage===0;$('next').disabled=currentPage>=pageGroups().length-1}};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_pdf_layout',description:'Read the image order and configured PDF page layout.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({images:images.map(x=>({id:x.id,name:x.name})),settings:structuredClone(settings),pages:pageGroups().length})})).catch(()=>{})}catch{}}
settingsUI();refresh(true);

